package com.airesumebuilder.feature.notification.service;import com.airesumebuilder.common.exception.ResourceNotFoundException;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final NotificationRepository r;public NotificationService(NotificationRepository r){this.r=r;}@Transactional(readOnly=true)public List<Item>list(String e,boolean unread){return r.list(e,unread);}@Transactional public Item read(String e,long id){return r.read(e,id);}@Transactional public int readAll(String e){return r.readAll(e);}@Transactional(readOnly=true)public Preferences preferences(String email){return r.preferences(email);}@Transactional public Preferences updatePreferences(String email,Preferences preferences){return r.updatePreferences(email,preferences);}public record Item(long id,String type,String title,String body,String status,Instant readAt,Instant createdAt){} public record Preferences(boolean emailEnabled,boolean inAppEnabled,boolean jobAlertsEnabled,boolean aiUpdatesEnabled){} }
@Repository class NotificationRepository{private final JdbcTemplate j;NotificationRepository(JdbcTemplate j){this.j=j;}List<NotificationService.Item>list(String e,boolean unread){return j.query("SELECT n.* FROM notifications n JOIN users u ON u.id=n.user_id WHERE u.email=?"+(unread?" AND n.read_at IS NULL":"")+" ORDER BY n.created_at DESC",this::map,e);}NotificationService.Item read(String e,long id){if(j.update("UPDATE notifications n JOIN users u ON u.id=n.user_id SET n.status='READ',n.read_at=COALESCE(n.read_at,NOW(6)) WHERE u.email=? AND n.id=?",e,id)==0)throw new ResourceNotFoundException("Notification not found.");return j.query("SELECT n.* FROM notifications n JOIN users u ON u.id=n.user_id WHERE u.email=? AND n.id=?",this::map,e,id).getFirst();}int readAll(String e){return j.update("UPDATE notifications n JOIN users u ON u.id=n.user_id SET n.status='READ',n.read_at=COALESCE(n.read_at,NOW(6)) WHERE u.email=? AND n.read_at IS NULL",e);}NotificationService.Preferences preferences(String email){return j.query("SELECT p.* FROM user_notification_preferences p JOIN users u ON u.id=p.user_id WHERE u.email=?",this::preferences,email).stream().findFirst().orElse(new NotificationService.Preferences(true,true,true,true));}NotificationService.Preferences updatePreferences(String email,NotificationService.Preferences p){j.update("INSERT INTO user_notification_preferences (user_id,email_enabled,in_app_enabled,job_alerts_enabled,ai_updates_enabled) SELECT id,?,?,?,? FROM users WHERE email=? ON DUPLICATE KEY UPDATE email_enabled=VALUES(email_enabled),in_app_enabled=VALUES(in_app_enabled),job_alerts_enabled=VALUES(job_alerts_enabled),ai_updates_enabled=VALUES(ai_updates_enabled)",p.emailEnabled(),p.inAppEnabled(),p.jobAlertsEnabled(),p.aiUpdatesEnabled(),email);return preferences(email);}private NotificationService.Preferences preferences(ResultSet r,int n)throws SQLException{return new NotificationService.Preferences(r.getBoolean("email_enabled"),r.getBoolean("in_app_enabled"),r.getBoolean("job_alerts_enabled"),r.getBoolean("ai_updates_enabled"));}private NotificationService.Item map(ResultSet r,int n)throws SQLException{Timestamp t=r.getTimestamp("read_at");return new NotificationService.Item(r.getLong("id"),r.getString("type"),r.getString("title"),r.getString("body"),r.getString("status"),t==null?null:t.toInstant(),r.getTimestamp("created_at").toInstant());}}
